import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {isDeepStrictEqual} from 'node:util';
import {sha256,publicEvidence,readEvidence} from '../../../scripts/eval/p2/artifacts.ts';
import {aggregateScores,allRealScores,rescoreRun} from '../../../scripts/eval/p2/rescore.ts';
import {scoreEvidenceV2} from '../../../scripts/eval/p2/score-v2.ts';
import {scoreProgram} from '../../../scripts/eval/p2/program-score.ts';
const base='story/testing/runs/P2R',folder=base+'/P2-ACCEPTANCE/20261031-d4-final',read=p=>JSON.parse(readFileSync(p,'utf8'));
const summary=read(folder+'/summary.json'),bundle=read(folder+'/approved-score-overlays.json'),approval=read(bundle.approvalPath),freeze=summary.repositoryCommit;
const git=(...args)=>{const r=spawnSync('git',['--no-optional-locks',...args],{encoding:'utf8',windowsHide:true});if(r.status!==0)throw Error('Git unavailable');return r.stdout.trim();};
const exclusions=[':(exclude)story/testing/runs',':(exclude)story/testing/README.md',':(exclude)docs/p2r/report.md',':(exclude)docs/adr/ADR-020-P2执行环境迁移与重新冻结.md'];
if(git('diff','--name-only',freeze,'--','.',...exclusions)||git('status','--porcelain=v1','--untracked-files=all','--','.',...exclusions))throw Error('Frozen implementation changed');
for(const f of approval.originalJudgmentFiles)if(sha256(readFileSync(f.path))!==f.sha256)throw Error('Source judgment changed');
const runs=[];
for(const x of summary.selectedRuns){
 const overlay=bundle.overlays.find(o=>o.runId===x.runId);if(!overlay)throw Error('Missing approved overlay');
 if(overlay.approvalSha256!==sha256(readFileSync(bundle.approvalPath)))throw Error('Approval digest mismatch');
 const metrics=scoreEvidenceV2(readEvidence(x.folder,true),overlay.judgments);if(!isDeepStrictEqual(metrics,overlay.metrics))throw Error('Derived score drift');
 if(!rescoreRun(x.folder).equal)throw Error('Source pending metric not reproducible');
 const m=read(x.folder+'/run-manifest.json');if(m.repositoryCommit!==freeze||m.dirty)throw Error('Wrong raw source');
 x.metricsSha256=sha256(readFileSync(x.folder+'/metrics.json'));x.approvedMetricsSha256=sha256(JSON.stringify(metrics));
 x.approvedMetricsSource=folder+'/approved-score-overlays.json#'+x.runId;
 runs.push({...x,metrics:metrics.metrics});
}
const quality=aggregateScores(runs,'p2r-24@1');if(!isDeepStrictEqual(quality,summary.quality))throw Error('Effective acceptance values changed');
const extra=[
 base+'/P2-CHAP/20261031T074430Z-0ae2186-r2',base+'/P2-EDIT/20261031T083200Z-0ae2186-r2',
 base+'/P2-REG/20261031T063135Z-0ae2186',base+'/P2-UNIT/20261031T063318Z-0ae2186',
 base+'/P2-GUARD/20261031T063354Z-0ae2186',base+'/P2-FOLD/20261031T063403Z-0ae2186',base+'/P2-CTX/20261031T063412Z-0ae2186-acceptance'];
const payload=runs.map(x=>({folder:x.folder,suiteId:x.suiteId,repetition:x.repetition,equal:true,mode:'approved_derived_metrics',sourceMetricsEqual:true,sourceManifestSha256:x.manifestSha256,originalMetricsSha256:x.metricsSha256,approvedMetricsSha256:x.approvedMetricsSha256}));
for(const p of extra){const m=read(p+'/run-manifest.json');if(m.repositoryCommit!==freeze||m.dirty)throw Error('Wrong extra source');const r=rescoreRun(p);if(!r.equal)throw Error('Raw rescore drift');payload.push({folder:p,suiteId:m.suiteId,...(m.repetition===undefined?{}:{repetition:m.repetition}),equal:r.equal,mode:'original_metrics',sourceManifestSha256:sha256(readFileSync(p+'/run-manifest.json')),originalMetricsSha256:sha256(readFileSync(p+'/metrics.json'))});}
if(payload.length!==13||new Set(payload.map(x=>x.folder)).size!==13)throw Error('Wrong rescore cohort');
summary.approvalSha256=sha256(readFileSync(bundle.approvalPath));summary.approvedScoreOverlaysSha256=sha256(readFileSync(folder+'/approved-score-overlays.json'));
summary.evidenceHead=git('rev-parse','HEAD');summary.quality=quality;summary.allReal=allRealScores(base,freeze);
summary.scoringApplication='Author-approved corrections are applied only to independently stored derived scores; source judgments and metrics remain unchanged.';
summary.sourceEquivalence.currentDifferencesOutsideRuns=git('diff','--name-only',freeze,'--','.',':(exclude)story/testing/runs');
summary.sourceEquivalence.note='Implementation equals V2. Handoff testing README and the execution report/ADR closeout are the only source-tree differences; no whole-tree equality or clean freeze CLI invocation is claimed.';
summary.rescorePath=folder+'/rescore.json';
const raw={suiteId:'P2-RESCORE',runId:'20261031-author-approved-overlay',payload};
const result={schema:'story/p2r-offline-rescore@1',sourceFreeze:freeze,evidenceHead:summary.evidenceHead,currentSourceDirty:git('status','--porcelain=v1','--','.',':(exclude)story/testing/runs')!=='',sourceEquivalence:summary.sourceEquivalence,approvalPath:bundle.approvalPath,approvalSha256:summary.approvalSha256,raw,metrics:scoreProgram(raw),modelRequests:0,notes:['Six approved derived scores are recomputed using frozen scoreEvidenceV2; their original pending source metrics are independently reproduced.','Two cancelled real cohorts plus five deterministic suites use unchanged original metrics. No cancelled cohort is added to quality.']};
const json=x=>{const t=JSON.stringify(x,null,2)+'\n';publicEvidence(t);return t;};
if(process.argv.includes('--check')){
 const previous=read(folder+'/rescore.json');if(!isDeepStrictEqual(previous.raw,raw)||!isDeepStrictEqual(previous.metrics,result.metrics))throw Error('Saved offline rescore differs');
}else{
 writeFileSync(folder+'/summary.json',json(summary));writeFileSync(folder+'/rescore.json',json(result));
 const source=readFileSync(import.meta.filename,'utf8');writeFileSync(folder+'/reproduction.json',json({schema:'story/reproduction-source@1',scriptPath:'story/testing/exec/temp/p2r-final-offline.mjs',source,sourceSha256:sha256(source),instructions:'Restore at scriptPath, run node <scriptPath> --check to recompute approved derived scores and all 13 comparisons without changing files. Same frozen scorer, original manifests/raw, approved score overlay and author approval are required.'}));
}
console.log(JSON.stringify({runs:payload.length,approvedDerivedRuns:runs.length,originalJudgmentFilesUnchanged:31,originalSourceMetricsEqual:13,metrics:result.metrics.metrics}));
